from lib import *
S = SS('g11')
L3 = S(3)
steps = [
    step("同一个 10 个键的 map,在同一个进程里 for range 5 次:第 1、2、3 次是 a b c d e f g h i j,第 4 次 i j a b c d e f g h,第 5 次 b c d e f g h i j a——不是每次都变,但起点会变,而且看起来是同一个环从不同位置读起。", t=tl(S(1)), done=lidx(S(1), '第 1 次', '第 2 次', '第 3 次'), mark=lidx(S(1), '第 4 次', '第 5 次'), kv=KV([['第 1–3 次', 'a b c d e f g h i j'], ['第 4 次', 'i j a b c d e f g h'], ['第 5 次', 'b c d e f g h i j a']], ['第 4 次'])),
    step("第一个被遍历到的键的分布(每个 map 遍历 10000 次):8 个键:出现过 8 个不同的首键,期望每个 1250 次,最少 1223、最多 1296;100 个键:出现过 100 个不同的首键,期望每个 100 次,但最少 59、最多 456——不是均匀的。", t=tl(S(2)), done=lidx(S(2), '8 个键'), mark=lidx(S(2), '100 个键'), b=bars([['8 个键:最少', 1223, '1223'], ['8 个键:最多', 1296, '1296'], ['100 个键:最少', 59, '59'], ['100 个键:最多', 456, '456']], 1296, done=[0, 1], mark=[2, 3]), kv=KV([['8 个键', '首键次数 1223–1296(期望 1250)'], ['100 个键', '首键次数 59–456(期望 100)']], ['100 个键'])),
    step("数不同的完整顺序:5、8、9、20、100 个键各遍历 5000 次,分别只出现 5、8、9、20、100 种不同的顺序,而且全都是第一次顺序的旋转(true);1000、2000、20000 个键各遍历 3000 次,出现了 1030、1734、2878 种,不再全是旋转(false)。", t=tl(L3), done=lidx(L3, '5 个键', '8 个键', '9 个键', '20 个键', '100 个键'), mark=lidx(L3, '1000 个键', '2000 个键', '20000 个键'), b=bars([['100 个键:不同顺序数', 100, '100'], ['1000 个键', 1030, '1030'], ['2000 个键', 1734, '1734'], ['20000 个键', 2878, '2878']], 2878, done=[0], mark=[1, 2, 3]), kv=KV([['≤ 100 个键(一张表)', '不同顺序 = 键数,全是旋转'], ['≥ 1000 个键(多张表)', '不同顺序超过键数,不再是单纯的旋转']], ['≥ 1000 个键(多张表)'])),
    step("遍历时修改:每次遍历第一个键时删除另一个还没遍历到的键,重复 2000 次,被删除的键被遍历到 0 次;遍历时新增键 100,重复 2000 次,新增的键被遍历到 1753 次。删除的一定不会出现,新增的可能出现。", t=tl(S(4)), done=lidx(S(4), '被遍历到 0 / 2000 次'), mark=lidx(S(4), '1753 / 2000 次'), b=bars([['删除未遍历的键:被遍历到', 0, '0 / 2000'], ['遍历中新增的键:被遍历到', 1753, '1753 / 2000']], 2000, done=[0], mark=[1]), kv=KV([['遍历中删除还没遍历到的键', '0 / 2000 次被遍历到'], ['遍历中新增键', '1753 / 2000 次被遍历到']], ['遍历中新增键'])),
    step("需要确定的顺序时:fmt.Println(m) 输出 map[apple:1 banana:2 cherry:3 date:4],按键排序;json.Marshal 输出 {\"apple\":1,\"banana\":2,\"cherry\":3,\"date\":4},按键排序;自己遍历用 slices.Sorted(maps.Keys(m)) 得到 [apple banana cherry date];for range nil map 循环 0 次,不 panic。", t=tl(S(5)), done=lidx(S(5), 'fmt.Println', 'json.Marshal'), mark=lidx(S(5), 'slices.Sorted', 'nil map'), kv=KV([['fmt.Println(m)', '按键排序'], ['json.Marshal(m)', '按键排序'], ['slices.Sorted(maps.Keys(m))', '自己遍历前先排序'], ['for range nil map', '0 次,不 panic']], ['slices.Sorted(maps.Keys(m))'])),
    step("随机数从哪来:internal/runtime/maps/table.go 里迭代器初始化的片段是 it.entryOffset = rand() 与 it.dirOffset = rand()——每次开始遍历都取两个随机数,一个决定组内与组之间的起始偏移,一个决定从目录里哪张表开始。再启动 3 个新进程,各自第 1 次遍历的顺序是 c e g i j a d f h b、a c d e g h j b f i、h i j b d g a c e f,连环本身的顺序也不同(哈希种子每个 map 不同)。", t=tl(S(6)), done=lidx(S(6), 'it.entryOffset = rand()', 'it.dirOffset = rand()'), mark=lidx(S(6), '再启动 3 个新进程'), kv=KV([['it.entryOffset', '= rand()(每次遍历)'], ['it.dirOffset', '= rand()(每次遍历)'], ['3 个新进程', '三种不同的环与起点']], ['it.entryOffset'])),
]
A = mkartg('g11', 11, 'Go,map,遍历顺序,随机,真实验证,动画演示',
    '在 Go 1.27.1 里实测 map 遍历顺序:同一个 map 每次遍历的起点不同;键数不超过 100 时,所有顺序都只是同一个环的旋转(100 个键只出现 100 种顺序),上千个键、多张表时才出现更多顺序;首键分布并不均匀(100 个键最少 59 次、最多 456 次);遍历时删除的键一定不出现、新增的键约 88% 出现;随机数来自迭代器初始化时的两个 rand()。',
    '“map 遍历是随机的”这句话到底随机到什么程度?这篇不凭印象,而是遍历上万次,数首个键的分布、数不同的完整顺序、验证遍历中修改的结果,再指到运行时源码里取随机数的那两行。',
    [('旋转', '≤ 100 个键的 map,5000 次遍历只出现与键数相同的几种顺序,全是同一个环的旋转'), ('59 / 456', '100 个键的 map 遍历 10000 次,各个键作为第一个的次数,最少与最多(均匀应约 100)'), ('0 / 2000', '遍历中被删除、还没遍历到的键,被遍历到的次数')],
    [('同一个 map,不同的起点', '<p>Go 语言规范只说遍历顺序是不确定的;运行时则主动加了随机:每次开始 <code>for range</code> 都取随机偏移。所以不能依赖某次运行里看到的顺序,哪怕在测试里它碰巧稳定。</p>'),
     ('不是均匀随机', '<p>8 个键时首键基本均匀(1223–1296),但 100 个键时差距很大(59–456)。原因我没有逐项验证,合理的猜测是:随机起点落在“槽”上而不是“键”上,而键之间隔着数量不等的空槽,前面空槽多的键更容易成为第一个。要靠遍历的随机性来做公平选择(比如随机选一个元素)是不可靠的,应该用 <code>math/rand/v2</code>。</p>'),
     ('只是旋转吗', '<p>在一张表内(这里到 100 个键为止),随机的只有起点,顺序是同一个环的旋转,所以 100 个键只有 100 种顺序。键数上千、map 由多张表组成时,每张表的起点和表之间的起点分别变化,出现的顺序数才超过键数。这与上一篇里“map 由最多 1024 个槽的多张表组成”的设计一致。</p>'),
     ('遍历时修改', '<p>规范规定遍历中删除了还没遍历到的键,它就不会被遍历到(实测 0 / 2000);遍历中新增的键则“可能”被遍历到(实测 1753 / 2000,与新键落在已遍历位置之前还是之后有关,我没有分别统计)。</p>'),
     ('要确定顺序时', '<p><code>fmt</code> 打印 map 时按键排序(源码 <code>fmt/print.go</code> 打印 map 时调用 <code>internal/fmtsort</code> 的 <code>Sort</code>),<code>encoding/json</code> 的输出也是排好序的(上面的实测);自己遍历时先取出键排序。<code>maps.Keys</code> 返回的是迭代器,配合 <code>slices.Sorted</code> 一行就够。</p>'),
     ('随机从哪里来', '<p>迭代器初始化的代码里取了两个随机数:<code>entryOffset</code> 与 <code>dirOffset</code>。另外每个 map 在创建时有自己的哈希种子,所以环本身的顺序在不同进程、不同 map 之间也不同(上面 3 个新进程各给出不同的顺序)。</p>')],
    steps,
    [ENV_G + '。读过的源码:internal/runtime/maps/table.go 里迭代器初始化的片段(原样列在第六节)、fmt/print.go 里对 internal/fmtsort 的调用;遍历次数与结果来自程序里的计数;“多张表”与键数的对应只是对实验结果的解释,没有直接观察每次遍历访问了几张表',
     '没有验证:首键分布不均匀的原因(槽上随机起点)、遍历中新增键出现概率与位置的关系、扩容进行中遍历的语义(Swiss map 的迭代器实现细节)、字符串键与更大元素的 map、maps.Keys / slices.Sorted 的开销'],
    'map 的遍历顺序')
